import { VerticalStackedBarChart } from './charts/VerticalStackedBarChart';
```

## Data Formats

### StackedBarDataPoint (Legacy)

```tsx
interface StackedBarDataPoint {
  label: string; // Category label (e.g., "Jan")
  segments: StackedBarSegment[]; // Array of segments (max 6)
  totalLabel?: string; // Optional custom total label
}
```

### StackedBarSegment

```tsx
interface StackedBarSegment {
  value: number; // Segment value
  label?: string; // Segment label (for legend)
  color?: string; // Custom color override
}
```

## Props Interface (Organized Props Pattern)

```tsx
import { StackedBarDataPoint } from "../../groups/VerticalStackedBarGroup";
import { ChartLegendItem } from "../../groups/ChartLegend";
import { ValueFormatConfig } from "../../groups/VerticalStackedBarGroup";

/** Props for the ChartHeader child component */
type ChartHeaderConfig = Pick<
  ChartHeaderProps,
  "chartTitleValue" | "chartSubtitleValue" | "title" | "subtitle" | "titleId" | "subtitleId"
>;

/** Props for the ChartLegend child component */
interface ChartLegendConfig {
  items?: ChartLegendItem[];
  type?: "circle" | "dashed" | "line";
  dataHead?: boolean;
  dataHeadConfig?: {
    dataLeadValue?: number | string;
    dataSupportingValue?: number | string;
    supportingLabelValue?: string;
    supportingData?: boolean;
    supportingLabel?: boolean;
  };
  /** Updates legend item(s) DataHead lead value on hover. Requires `dataHead: true`.
   * "individual"/"categorical" hoverType updates only the hovered series; "group"
   * hoverType updates every series at once with that category's breakdown. */
  interactiveDataHead?: boolean;
  formatHoverSupportingLabel?: (category: CategoryValue, seriesIndex: number) => string;
  size?: "XS" | "S" | "M" | "L" | "XL";
  ariaLabel?: string;
  ariaLabelledBy?: string;
}

/** Props for Y-Axis configuration */
interface YAxisConfig {
  tickCount?: number;
  formatValue?: (value: number) => string;
  valueFormat?: ValueFormatConfig;
  yAxisLabel?: boolean;
  yAxisLabelValue?: string;
  axisTickSkipper?: boolean;
  skippedTicks?: number[];
}

/** Props for AvgLine configuration */
interface AvgLineConfig {
  formatValue?: (value: number) => string;
  type?: "avg" | "threshold";
  thresholdValue?: number;
}

/** Props for Hover Badge configuration */
interface HoverBadgeConfig {
  formatValue?: (value: number, label?: string) => string;
  formatBadge?: (value: number, label?: string, secondaryValue?: number) => DataBadgeConfig;
  preset?: HoverBadgePreset;
}

/** Props for the VerticalStackedBarGroup child component */
interface BarGroupConfig {
  topLabels?: boolean;
  categoryLabels?: boolean;
  yAxis?: boolean;
  avgLine?: boolean;
  yAxisConfig?: YAxisConfig;
  avgLineConfig?: AvgLineConfig;
  valueFormat?: ValueFormatConfig;
  barWidth?: string;
  barHeightMode?: BarHeightMode; // 'fullHeight' | 'relative' (default: 'relative')
  hoverType?: StackedBarHoverType;
  hoverBadge?: boolean;
  hoverBadgeConfig?: HoverBadgeConfig;
  categoryLabelConfig?: CategoryLabelConfig;
  dataSort?: DataSortOrder; // "asc" | "desc" | "unsorted" (default: "unsorted")
  /** Enable entry and data-change animations with motion tokens (default: false) */
  animated?: boolean;
  onBarHover?: (data: VerticalStackedBarHoverData) => void;
  onBarClick?: (data: VerticalStackedBarHoverData) => void;
  /** Back-compat alias for `highlightedBarIndices`. */
  hoveredBarIndex?: number | number[];
  /** Indices of bars rendered at full opacity; every other bar dims. */
  highlightedBarIndices?: number[];
}

/** Props for the ChartFooter child component */
type ChartFooterConfig = Pick<
  ChartFooterProps,
  "annotationLeft" | "annotationLeftValue" | "annotationRight" | "annotationRightValue"
>;

/**
 * Props for the DataDisplay child component.
 * Mirrors DataDisplayProps structure (Layer 2 + Layer 3), with additional
 * chart-specific props for hover behaviour.
 * When mode is "hover", mainLabelValue, dataHead.dataLeadValue, and
 * badgeConfig.value updates dynamically on hover.
 */
interface DataDisplayConfig {
  // --- Chart-specific behaviour ---
  /** Display mode: "static" uses provided values, "hover" updates dynamically on hover (default: "static") */
  mode?: "static" | "hover";
  /** Custom formatter for lead value in hover mode (receives segment value, category, segmentIndex) */
  formatHoverLeadValue?: (value: number, category?: CategoryValue, segmentIndex?: number) => string;
  /** Custom formatter for badge value in hover mode (receives segment value, category, segmentIndex) */
  formatHoverBadgeValue?: (
    value: number,
    category?: CategoryValue,
    segmentIndex?: number
  ) => string;

  // --- DataDisplay Layer 2 props ---
  /** The main label text above the data value */
  mainLabelValue?: string;
  /** Layout alignment: "Left" (horizontal) or "Center" (vertical stacked) (default: "Left") */
  alignment?: "Left" | "Center";
  /** Toggle visibility of the rightBadgeWrapper section (default: true) */
  rightBadgeWrapper?: boolean;
  /** Toggle visibility of the badgeTop slot (default: false) */
  badgeTop?: boolean;
  /** Toggle visibility of the badgeBottom slot (default: true) */
  badgeBottom?: boolean;
  /** Toggle visibility of the OneUI Badge in supporting slots (default: true) */
  showBadge?: boolean;
  /** Toggle visibility of the supporting label next to the badge (default: true) */
  supportingBadgeLabel?: boolean;
  /** The supporting label text next to the badge */
  supportingBadgeLabelValue?: string;
  /** Local size variant for typography scaling: "XS", "S", "M", "L", or "XL" (default: "L") */
  size?: "XS" | "S" | "M" | "L" | "XL";

  // --- DataDisplay Layer 3 configs ---
  /** Configuration for the DataHead child component */
  dataHead?: DataHeadConfig;
  /** Configuration for the Badge + SupportingLabel in supporting slots */
  badgeConfig?: BadgeConfig;
}

interface VerticalStackedBarChartProps {
  // Layer 2: Parent component props
  /**
   * Supports canonical format (ChartSeriesDataPoint[]) or legacy format (StackedBarDataPoint[])
   */
  data: ChartSeriesDataPoint[] | StackedBarDataPoint[];
  seriesOrder?: string[]; // Control segment stacking order for canonical format
  width?: number | string;
  height?: number | string;
  /** Stretch chart to fill parent container width. Default: false. */
  fullWidth?: boolean;
  chartHeader?: boolean;
  chartFooter?: boolean;
  chartLegend?: boolean;
  dataDisplay?: boolean; // Show DataDisplay component above bars
  interactive?: boolean;
  animated?: boolean;

  // Layer 3: Child component configurations
  chartHeaderConfig?: ChartHeaderConfig;
  chartLegendConfig?: ChartLegendConfig;
  dataDisplayConfig?: DataDisplayConfig; // Configuration for DataDisplay
  barGroupConfig?: BarGroupConfig;
  chartFooterConfig?: ChartFooterConfig;

  // Accessibility
  /** Accessibility configuration for screen readers */
  accessibility?: AccessibilityConfig;
}
```

